Here’s a Flask implementation using SQLAlchemy, Werkzeug password hashing, and Flask-Login.

```bash
pip install Flask Flask-SQLAlchemy Flask-Login
```

```python
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_login import (
    LoginManager,
    UserMixin,
    login_user,
    logout_user,
    login_required,
)
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = "replace-with-an-environment-variable"
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///users.db"
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SECURE"] = True  # Use HTTPS in production

db = SQLAlchemy(app)
login_manager = LoginManager(app)


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)


@login_manager.user_loader
def load_user(user_id):
    return db.session.get(User, int(user_id))


@app.post("/register")
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")

    if not username or not password:
        return jsonify(error="Username and password are required"), 400

    if len(password) < 8:
        return jsonify(error="Password must be at least 8 characters"), 400

    if User.query.filter_by(username=username).first():
        return jsonify(error="Username already exists"), 409

    user = User(username=username)
    user.set_password(password)

    db.session.add(user)
    db.session.commit()

    return jsonify(message="User registered successfully"), 201


@app.post("/login")
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")

    user = User.query.filter_by(username=username).first()

    if user is None or not user.check_password(password):
        return jsonify(error="Invalid username or password"), 401

    login_user(user)
    return jsonify(message="Logged in successfully"), 200


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return jsonify(message="Logged out successfully"), 200


@app.get("/dashboard")
@login_required
def dashboard():
    return jsonify(message="Welcome to your dashboard")


with app.app_context():
    db.create_all()

if __name__ == "__main__":
    app.run(port=5000)
```

Test login with:

```bash
curl -X POST http://localhost:5000/login \
  -H "Content-Type: application/json" \
  -d '{"username":"testuser","password":"testpass123"}'
```

For production, use an environment variable for `SECRET_KEY`, HTTPS, secure cookies, rate limiting, and generic login error messages.

